<?php $e=static fn(mixed $value):string=>App\Core\View::e($value); ?>
<section><div class="section-heading"><div><p class="eyebrow">Simulação interna</p><h1>Novo cenário</h1><p>Use somente para projeções. Nada deste formulário vira dado oficial.</p></div></div><?php foreach($errors as $error): ?><p class="error"><?= $e($error) ?></p><?php endforeach; ?><form method="post" class="form-grid" action="<?= $e(App\Core\Config::url('/admin/simulacoes')) ?>"><input type="hidden" name="_csrf" value="<?= $e(App\Core\Security::csrfToken()) ?>"><label>Nome<input name="name" required maxlength="160" value="<?= $e($record['name']??'') ?>"></label><label>Campeonato<select name="championship_id" required data-simulation-championship><option value="">Selecione</option><?php foreach($championships as $item): ?><option value="<?= (int)$item['id'] ?>"><?= $e($item['name']) ?></option><?php endforeach; ?></select></label><label>Fase<select name="phase_id" required data-simulation-phase><option value="">Selecione o campeonato</option><?php foreach($phases as $phase): ?><option value="<?= (int)$phase['id'] ?>" data-championship="<?= (int)$phase['championship_id'] ?>" hidden><?= $e($phase['name']) ?></option><?php endforeach; ?></select></label><label>Descrição<textarea name="description"><?= $e($record['description']??'') ?></textarea></label><label>Premissas<textarea name="assumptions"><?= $e($record['assumptions']??'') ?></textarea></label><label>Observações<textarea name="notes"><?= $e($record['notes']??'') ?></textarea></label><button type="submit">Criar cenário isolado</button></form><script>document.querySelector('[data-simulation-championship]')?.addEventListener('change',function(){document.querySelectorAll('[data-simulation-phase] option[data-championship]').forEach(option=>option.hidden=option.dataset.championship!==this.value);document.querySelector('[data-simulation-phase]').value='';});</script></section>
